━━━━━━━━━━━━━━━━━━━━━━
【図解】役員給与が損金になる3類型★
○定期同額給与：毎月同額の給与
○事前確定届出給与：支給時期・額を事前に税務署へ届出
○業績連動給与：一定の要件を満たす上場会社等
×これら以外（期中の増額分など）は損金不算入

・交際費：原則損金不算入だが、中小法人は年800万円まで損金算入可★
