　養子は実子がいれば1人・いなければ2人まで
・生命保険金・死亡退職金の非課税：各500万円×法定相続人の数★
→放棄者が受け取った保険金には非課税枠を使えない★
・弔慰金の非課税：業務上の死亡＝月給36か月分・業務外＝6か月分★
【図解】債務控除の○×
○借入金・未払いの医療費・未払いの税金
○通夜・葬式費用
×香典返し・法要（初七日等）の費用・墓地や仏壇の未払購入費★

